import {TILESET_RUNTIME} from './tileset-runtime-code.js';
const BASE=0x08000000,STOCK='3d0c79f1627022e18765766f6cb5ea067f6b5bf7dca115552189ad65a5c3a8ac';
const integer=(n,a,b)=>Number.isInteger(n)&&n>=a&&n<=b;
const fingerprint=bytes=>{let h=2166136261;for(const n of bytes)h=Math.imul(h^n,16777619);return h>>>0;};
export function tilesetAnimationProfile(reader,hash){if(hash!==STOCK)throw Error('Custom tileset loops need a compatible source animation table.');const p={init:0x70154,tick:0x70121,append:0x6ff05,initHash:2895647511};if(fingerprint(reader.bytes.slice(p.init,p.init+40))!==p.initHash||fingerprint(reader.bytes.slice(p.append-1,p.append-1+80))!==2450782232)throw Error('The native animation queue failed verification.');return p;}
export function validateTilesetAnimations(edits){if(edits===undefined)return;if(!edits||Array.isArray(edits)||Object.keys(edits).length>16||JSON.stringify(edits).length>8e6)throw Error('Invalid tileset animations.');for(const [hash,sets]of Object.entries(edits)){if(!/^[a-f0-9]{64}$/.test(hash)||!sets||Array.isArray(sets)||Object.keys(sets).length>64)throw Error('Invalid animation source.');for(const [key,e]of Object.entries(sets)){if(!/^\d+$/.test(key)||!e||typeof e.mapKey!=='string'||typeof e.keepNative!=='boolean'||!Array.isArray(e.clips)||e.clips.length>8)throw Error('Invalid tileset clip list.');for(const c of e.clips)if(!c||typeof c.name!=='string'||!c.name.trim()||c.name.length>80||!integer(c.tile,0,639)||!integer(c.tiles,1,32)||c.tile+c.tiles>640||!integer(c.ticks,1,60)||!Array.isArray(c.frames)||c.frames.length<2||c.frames.length>16||c.frames.some(f=>!Array.isArray(f)||f.length!==c.tiles*32||f.some(n=>!integer(n,0,255))))throw Error('A tileset loop needs 2–16 frames, 1–32 tiles and 1–60 ticks per frame.');}}}
const gcd=(a,b)=>b?gcd(b,a%b):a;
export function animationCycle(clips,keepNative){let cycle=keepNative?640:1;for(const c of clips){const n=c.ticks*c.frames.length;cycle=cycle/gcd(cycle,n)*n;if(cycle>65535)throw Error('These clip timings exceed the native counter. Use compatible periods, such as 4 frames at 8 or 16 ticks.');}return cycle;}
export function installTilesetAnimations(project,reader,hash,output,{copies=new Map(),staticArtwork=false}={}){
 const sets=project.tilesetAnimations?.[hash];if(!sets||!Object.values(sets).some(s=>s.clips.length))return[];validateTilesetAnimations({[hash]:sets});const p=tilesetAnimationProfile(reader,hash);if(staticArtwork)throw Error('Custom tileset loops need animated artwork. Turn off “Use static artwork” for this export.');const reports=[];
 for(const [headerText,e]of Object.entries(sets)){if(!e.clips.length)continue;const header=+headerText,map=reader.byKey(e.mapKey);if(!map||reader.ptr(map.layout.address+16)!==header)throw Error('An animated tileset no longer matches its source map.');const original=reader.u32(header+16),limit=reader.profile(map).graphicsCount;if(original&&original!==BASE+p.init+1)throw Error('This primary tileset uses a custom native initializer. Its adapter needs verification.');const occupied=new Set();for(const c of e.clips){if(c.tile+c.tiles>limit)throw Error('An animation crosses the primary tileset boundary.');for(let i=c.tile;i<c.tile+c.tiles;i++){if(occupied.has(i))throw Error('Two animation clips overwrite the same graphics tile.');occupied.add(i);if(e.keepNative&&original&&i>=416&&i<512)throw Error('This clip overlaps native flower/water animation tiles. Choose another range or disable native primary animation.');}}
  const cycle=animationCycle(e.clips,e.keepNative&&!!original),rows=new Uint8Array(e.clips.length*12),rv=new DataView(rows.buffer);for(const [i,c]of e.clips.entries()){const data=Uint8Array.from(c.frames.flat()),at=output.allocate(data,'Animation frames: '+c.name);rv.setUint32(i*12,BASE+at,true);for(const [j,n]of [c.tile,c.tiles,c.frames.length,c.ticks].entries())rv.setUint16(i*12+4+j*2,n,true);}const clips=BASE+output.allocate(rows,'Tileset animation clips'),template=Uint8Array.from(atob(TILESET_RUNTIME.bytes),c=>c.charCodeAt(0)),at=output.allocate(template,'Native tileset animation runtime'),view=new DataView(template.buffer),address=BASE+at;for(const off of TILESET_RUNTIME.relocations)view.setUint32(off,address+view.getUint32(off,true),true);
  const config={originalInit:e.keepNative?original:0,originalTick:e.keepNative&&original?BASE+p.tick:0,originalCycle:640,counter:0x03000fae,maximum:0x03000fb0,callback:0x03000fb8,append:BASE+p.append,clips,count:e.clips.length,cycle,tickEntry:address+TILESET_RUNTIME.symbols.anim_tick+1};for(const [i,key]of TILESET_RUNTIME.configFields.entries())if(key!=='magic')view.setUint32(TILESET_RUNTIME.symbols.anim_config+i*4,config[key],true);output.write(at,template);const init=address+TILESET_RUNTIME.symbols.anim_init+1;for(const target of [header,...(copies.get(header)||[])])output.int(target+16,init);reports.push('Tileset loops: '+e.clips.length+' · '+e.mapKey+' · shared primary tileset');
 }
 return reports;
}
export function animationFramePixels(frame,tiles){const width=Math.min(4,tiles)*8,height=Math.ceil(tiles/4)*8,pixels=new Uint8Array(width*height);for(let t=0;t<tiles;t++)for(let i=0;i<64;i++){const b=frame[t*32+(i>>1)],x=t%4*8+i%8,y=Math.floor(t/4)*8+(i>>3);pixels[y*width+x]=i%2?b>>>4:b&15;}return{width,height,pixels};}
export function paintAnimationPixel(frame,tiles,x,y,colour){const width=Math.min(4,tiles)*8,height=Math.ceil(tiles/4)*8;if(!integer(x,0,width-1)||!integer(y,0,height-1)||!integer(colour,0,15))return;const tile=Math.floor(y/8)*4+Math.floor(x/8);if(tile>=tiles)return;const at=tile*32+y%8*4+Math.floor(x%8/2);frame[at]=x%2?(frame[at]&15)|(colour<<4):(frame[at]&240)|colour;}
